-- Preserve any existing impact-gun add-ons and append each socket once.
UPDATE "Product" SET "addOns"="addOns" || ARRAY(SELECT socket.id FROM unnest(ARRAY['socket-axle-3','socket-axle-3-1-8','socket-axle-3-1-4','socket-axle-3-3-8','socket-axle-3-1-2','socket-axle-3-3-4','socket-axle-4','socket-deep-17mm','socket-deep-19mm','socket-deep-21mm','socket-deep-22mm','socket-deep-24mm','socket-deep-27mm','socket-deep-30mm','socket-deep-32mm','socket-deep-34mm','socket-deep-36mm','socket-deep-38mm','socket-deep-41mm','socket-deep-46mm','socket-deep-50mm','socket-deep-55mm']::text[]) WITH ORDINALITY AS socket(id,position) WHERE NOT socket.id=ANY("Product"."addOns") ORDER BY socket.position), "updatedAt"=CURRENT_TIMESTAMP WHERE "id"='impactgun';
